const SVG_LIMIT=1024*1024,CSS_LIMIT=64000;
export function sanitizeSvg(input){if(typeof input!=='string'||input.length>SVG_LIMIT)throw Error('SVG must be text smaller than 1 MB');if(!/^\s*<svg\b/i.test(input)||!/\<\/svg\>\s*$/i.test(input))throw Error('File is not a complete SVG');if((input.match(/</g)||[]).length>10000)throw Error('SVG is too complex');let out=input.replace(/<\?(?:xml)[^>]*\?>/gi,'').replace(/<!DOCTYPE[\s\S]*?>/gi,'').replace(/<(script|foreignObject|iframe|object|embed|audio|video|canvas|style)\b[\s\S]*?<\/\1\s*>/gi,'').replace(/<(script|foreignObject|iframe|object|embed|audio|video|canvas|style)\b[^>]*\/?\s*>/gi,'');out=out.replace(/\s+on[a-z-]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,'').replace(/\s+(href|xlink:href|src)\s*=\s*("|')\s*(?!#)[^"']*\2/gi,'').replace(/url\s*\(\s*(?!['"]?#)[^)]+\)/gi,'none').replace(/javascript\s*:/gi,'');if(/<(script|foreignObject|iframe|object|embed)\b|\son[a-z-]+\s*=|https?:\/\/|data:text\/html/i.test(out))throw Error('SVG contains unsafe executable or remote content');const viewBox=out.match(/\bviewBox\s*=\s*["']\s*([\d.+-]+)\s+([\d.+-]+)\s+([\d.+-]+)\s+([\d.+-]+)\s*["']/i);if(viewBox&&(!viewBox.slice(1).map(Number).every(Number.isFinite)||Number(viewBox[3])<=0||Number(viewBox[4])<=0||Number(viewBox[3])>100000||Number(viewBox[4])>100000))throw Error('SVG viewBox is invalid');if(!/<(path|rect|circle|ellipse|line|polyline|polygon|text|g|use|defs|linearGradient|radialGradient)\b/i.test(out))throw Error('SVG has no safe visible content after sanitization');return out;}
export function sanitizeScopedCss(input,scope){if(typeof input!=='string'||input.length>CSS_LIMIT)throw Error('Custom CSS must be smaller than 64 KB');if(!/^#[a-z][\w-]*$/i.test(scope))throw Error('Invalid CSS scope');const errors=[];let css=input.replace(/\/\*[\s\S]*?\*\//g,'');for(const bad of css.matchAll(/@(import|namespace|font-face|page|supports|document|charset)[^;{]*(?:;|\{[\s\S]*?\})/gi))errors.push(`Blocked @${bad[1]}`);css=css.replace(/@(import|namespace|font-face|page|supports|document|charset)[^;{]*(?:;|\{[\s\S]*?\})/gi,'');if(/url\s*\(/i.test(css)){errors.push('Blocked url()');css=css.replace(/url\s*\([^)]*\)/gi,'none');}if(/expression\s*\(|javascript:|behavior\s*:/i.test(css))throw Error('Custom CSS contains an executable value');let output='';for(const match of css.matchAll(/([^{}@]+)\{([^{}]*)\}/g)){const raw=match[1].trim(),body=match[2].trim();if(!raw||!body)continue;if(/[\[\]]/.test(raw)){errors.push(`Blocked attribute selector: ${raw}`);continue;}const selectors=raw.split(',').map(s=>s.trim()).filter(Boolean);if(selectors.some(s=>/:has\(|:host|:root|html|body|\*/i.test(s))){errors.push(`Blocked broad selector: ${raw}`);continue;}output+=selectors.map(s=>`${scope} ${s}`).join(', ')+' { '+body+' }\n';}if(output.length>CSS_LIMIT)throw Error('Scoped CSS result is too large');return {css:output,errors};}
